"""Post-call report: generated by Groq after hang-up, then *verified in code*.

Anti-hallucination design
  1. The transcript is numbered ([T1], [T2], ...). The LLM must cite the turn
     numbers supporting every need, objection, question, commitment and
     outcome.
  2. `ground_report()` checks those citations programmatically. Items citing
     no turn, a turn that doesn't exist, or a turn by the wrong speaker
     (e.g. a "customer objection" that only the agent said) are dropped and
     counted in `verification.removed_items`.
  3. A strong outcome ("sale", "callback", "do_not_call") with no valid
     evidence is downgraded to "unknown" and flagged for human review.
  4. The full transcript (original language + English) is attached to the
     report, so a reader can check every claim.
  5. The agent's statements are audited against the product facts
     (`compliance_flags`) to catch hallucinated prices or offers on the call.
"""

import html
import json
from datetime import datetime

from app import repositories as repo

OUTCOMES = {"sale", "interested", "callback", "not_interested", "do_not_call", "no_conversation", "unknown"}
STRONG_OUTCOMES = {"sale", "callback", "do_not_call", "not_interested"}

# Which speaker an item's evidence must come from
LIST_FIELDS = {
    "customer_needs": "customer",
    "objections": "customer",
    "questions_asked": "customer",
    "commitments": None,  # either side can state a next step
    "unanswered_requests": "customer",  # asked for something the product facts don't cover
    "compliance_flags": "agent",
}


def transcript_lines(messages: list[dict]) -> list[str]:
    """Numbered English transcript the LLM sees: [T1] AGENT: ... (agent flagged for follow-up: ...)"""
    lines = []
    for m in messages:
        line = f"[T{m['seq']}] {m['role'].upper()}: {m['content']}"
        if m.get("followups"):
            line += f" (agent flagged for follow-up: {'; '.join(m['followups'])})"
        lines.append(line)
    return lines


def merge_live_followups(report: dict, messages: list[dict]) -> None:
    """Add requests the agent flagged *during* the call (the [FOLLOWUP: ...] tag).

    These come from the live conversation, not from the report LLM, so a request can
    never go missing from the report even if the LLM overlooks it. Each one is linked
    to the customer turn just before the agent's reply."""
    items = report.setdefault("unanswered_requests", [])
    covered = {t for it in items for t in it["evidence"]}
    last_customer = None
    for m in messages:
        if m["role"] == "customer":
            last_customer = m["seq"]
            continue
        for text in m.get("followups") or []:
            evidence = [last_customer] if last_customer else [m["seq"]]
            if evidence[0] in covered:
                continue  # the report LLM already listed this request
            items.append({"text": text, "evidence": evidence, "source": "flagged live by agent"})
            covered.add(evidence[0])


def transcript_for_report(messages: list[dict]) -> list[dict]:
    """The full conversation, stored inside the report so it is complete on its own."""
    keep = ("seq", "role", "original", "content", "language", "interrupted", "kind", "followups", "created_at")
    return [{k: m.get(k) for k in keep if k in m} for m in messages]


def _turns(value) -> list[int]:
    out = []
    for v in value if isinstance(value, list) else [value]:
        try:
            out.append(int(str(v).strip().lstrip("Tt[").rstrip("]")))
        except (TypeError, ValueError):
            continue
    return out


def ground_report(raw: dict, messages: list[dict]) -> dict:
    """Validate the LLM report against the real transcript and return a clean report."""
    roles = {m["seq"]: m["role"] for m in messages}
    removed: list[dict] = []
    report: dict = {}

    outcome = raw.get("outcome") if raw.get("outcome") in OUTCOMES else "unknown"
    outcome_ev = [t for t in _turns(raw.get("outcome_evidence", [])) if t in roles]
    needs_review = False
    if not messages:
        outcome = "no_conversation"
    elif outcome in STRONG_OUTCOMES and not outcome_ev:
        removed.append({"field": "outcome", "text": outcome, "reason": "no valid evidence"})
        outcome, needs_review = "unknown", True
    report["outcome"] = outcome
    report["outcome_evidence"] = outcome_ev
    report["sentiment"] = (
        raw.get("sentiment") if raw.get("sentiment") in {"positive", "neutral", "negative"} else "neutral"
    )
    report["summary"] = str(raw.get("summary") or "").strip()

    for field, required_role in LIST_FIELDS.items():
        kept = []
        for item in raw.get(field) or []:
            if not isinstance(item, dict) or not str(item.get("text", "")).strip():
                continue
            valid = [t for t in _turns(item.get("evidence", [])) if t in roles]
            if required_role:
                valid = [t for t in valid if roles[t] == required_role]
            if not valid:
                removed.append({"field": field, "text": item.get("text"), "reason": "evidence missing or invalid"})
                continue
            clean = {"text": str(item["text"]).strip(), "evidence": sorted(set(valid))}
            if field == "questions_asked":
                clean["answered"] = bool(item.get("answered"))
            kept.append(clean)
        report[field] = kept

    callback = raw.get("callback_time")
    report["callback_time"] = str(callback).strip() if callback and str(callback).lower() != "null" else None
    report["verification"] = {
        "method": "every item must cite transcript turns by the right speaker; checked in code",
        "removed_items": removed,
        "needs_human_review": needs_review or bool(report["compliance_flags"]),
    }
    return report


async def build_call_report(llm, call: dict, customer: dict, product: dict, messages: list[dict]) -> dict:
    """Generate + verify the report. Never raises: a failed LLM call yields a minimal report."""
    from app.services.llm import format_product_facts

    raw: dict = {}
    error = None
    if messages:
        try:
            raw = await llm.generate_report(transcript_lines(messages), format_product_facts(product))
        except Exception as exc:  # keep the transcript even if the LLM is down
            error = str(exc)
    report = ground_report(raw, messages)
    merge_live_followups(report, messages)
    report["follow_up_required"] = bool(report["unanswered_requests"])
    report["transcript"] = transcript_for_report(messages)
    if error:
        report["verification"]["error"] = f"LLM report generation failed: {error}"
        report["verification"]["needs_human_review"] = True
    report["meta"] = {
        "call_id": call.get("id"),
        "customer": {
            "name": call.get("customer_name") or customer.get("name"),
            "phone": call.get("phone") or customer.get("phone"),
        },
        "batch_id": call.get("batch_id"),
        "product": {"sku": product.get("sku"), "name": product.get("name")},
        "language": call.get("language"),
        "status": call.get("status"),
        "duration_s": call.get("duration_s"),
        "started_at": call.get("created_at"),
        "ended_at": call.get("ended_at"),
        "generated_at": datetime.now().astimezone(),
    }
    return report


async def create_report_for_call(llm, call_id: str) -> dict | None:
    """Load everything for a call from MongoDB, build the verified report and store it."""
    call = await repo.get_call(call_id)
    if not call:
        return None
    customer = await repo.get_customer(call["customer_id"]) or {}
    product = await repo.get_product(call["product_sku"]) or {}
    messages = await repo.get_messages(call_id)
    report = await build_call_report(llm, call, customer, product, messages)
    await repo.save_report(call_id, report)
    return report


RENDERERS = {
    "md": ("text/markdown; charset=utf-8", "md"),
    "html": ("text/html; charset=utf-8", "html"),
    "json": ("application/json", "json"),
}


def render(report: dict, messages: list[dict], fmt: str) -> str:
    # Prefer the conversation stored inside the report (complete on its own)
    messages = report.get("transcript") or messages
    return {"md": render_markdown, "html": render_html, "json": render_json}[fmt](report, messages)


# ---------------------------------------------------------------- rendering
def _fmt_dt(value) -> str:
    if isinstance(value, datetime):
        return value.strftime("%d %b %Y, %H:%M %Z").strip()
    return str(value or "-")


def _ev(evidence: list[int]) -> str:
    return ", ".join(f"T{t}" for t in evidence)


def render_markdown(report: dict, messages: list[dict]) -> str:
    meta = report["meta"]
    lines = [
        f"# Call report: {meta['customer'].get('name') or 'Customer'}",
        "",
        f"- **Product:** {meta['product'].get('name')} ({meta['product'].get('sku')})",
        f"- **Phone:** {meta['customer'].get('phone')}",
        f"- **Language:** {meta.get('language') or '-'}",
        f"- **Date:** {_fmt_dt(meta.get('started_at'))}",
        f"- **Duration:** {meta.get('duration_s') or '-'} s",
        f"- **Outcome:** {report['outcome'].replace('_', ' ')}"
        + (f" (evidence: {_ev(report['outcome_evidence'])})" if report["outcome_evidence"] else ""),
        f"- **Sentiment:** {report['sentiment']}",
        f"- **Callback time:** {report['callback_time'] or '-'}",
        f"- **Needs follow-up:** {'yes, ' + str(len(report.get('unanswered_requests') or [])) + ' request(s) the product facts do not cover' if report.get('unanswered_requests') else 'no'}",
        "",
        "## Summary",
        "",
        report["summary"] or "_No summary available._",
        "",
    ]
    sections = [
        ("Customer needs", "customer_needs"),
        ("Objections", "objections"),
        ("Questions asked", "questions_asked"),
        ("Commitments and next steps", "commitments"),
        ("Needs follow-up: requests the agent couldn't answer from the product facts", "unanswered_requests"),
        ("Compliance flags (agent statements not backed by product facts)", "compliance_flags"),
    ]
    for title, key in sections:
        lines += [f"## {title}", ""]
        items = report.get(key) or []
        if not items:
            lines.append("- None")
        for it in items:
            extra = ""
            if key == "questions_asked":
                extra = " (answered)" if it.get("answered") else " (not answered)"
            lines.append(f"- {it['text']}{extra} [{_ev(it['evidence'])}]")
        lines.append("")
    v = report["verification"]
    lines += [
        "## Verification",
        "",
        f"- Every item above cites the transcript turns it came from (T-numbers below). "
        f"{len(v['removed_items'])} unsupported item(s) were removed automatically.",
        f"- Needs human review: **{'yes' if v['needs_human_review'] else 'no'}**",
    ]
    if v.get("error"):
        lines.append(f"- {v['error']}")
    lines += ["", "## Transcript", "", "| Turn | Speaker | What was said | English |", "|---|---|---|---|"]
    for m in messages:
        orig = m["original"].replace("|", "\\|").replace("\n", " ")
        eng = m["content"].replace("|", "\\|").replace("\n", " ")
        lines.append(f"| T{m['seq']} | {m['role']} | {orig} | {eng if eng != orig else ''} |")
    lines += ["", f"_Generated {_fmt_dt(meta.get('generated_at'))}_", ""]
    return "\n".join(lines)


