def render_html(report: dict, messages: list[dict]) -> str:
    e = html.escape
    meta = report["meta"]

    def items(key: str) -> str:
        rows = report.get(key) or []
        if not rows:
            return "<p class='ev'>None</p>"
        out = []
        for it in rows:
            extra = ""
            if key == "questions_asked":
                extra = " (answered)" if it.get("answered") else " (not answered)"
            out.append(f"<li>{e(it['text'])}{extra} <span class='ev'>[{e(_ev(it['evidence']))}]</span></li>")
        return "<ul>" + "".join(out) + "</ul>"

    v = report["verification"]
    flags = (
        f"<p class='flag'>Flagged for human review. {len(report['compliance_flags'])} compliance flag(s).</p>"
        if v["needs_human_review"]
        else ""
    )
    if report.get("unanswered_requests"):
        flags += (
            f"<p class='flag'>Needs follow-up: the customer asked {len(report['unanswered_requests'])} "
            "thing(s) the product facts don't cover. See below.</p>"
        )
    rows = "".join(
        f"<tr class='{e(m['role'])}'><td>T{m['seq']}</td><td>{e(m['role'])}</td>"
        f"<td>{e(m['original'])}</td><td>{e(m['content']) if m['content'] != m['original'] else ''}</td></tr>"
        for m in messages
    )
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Call report – {e(meta["customer"].get("name") or "Customer")}</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Noto+Sans:wght@400;600&family=Noto+Sans+Gujarati&family=Noto+Sans+Devanagari&display=swap">
<style>{_CSS}</style></head><body><main>
<h1>Call report: {e(meta["customer"].get("name") or "Customer")}</h1>
<span class="outcome">{e(report["outcome"].replace("_", " "))}</span>
<span class="ev">{("evidence: " + e(_ev(report["outcome_evidence"]))) if report["outcome_evidence"] else ""}</span>
<div class="meta">
<div><b>Product</b>{e(str(meta["product"].get("name")))}</div>
<div><b>Phone</b>{e(str(meta["customer"].get("phone")))}</div>
<div><b>Language</b>{e(str(meta.get("language") or "-"))}</div>
<div><b>Date</b>{e(_fmt_dt(meta.get("started_at")))}</div>
<div><b>Duration</b>{e(str(meta.get("duration_s") or "-"))} s</div>
<div><b>Sentiment</b>{e(report["sentiment"])}</div>
<div><b>Callback time</b>{e(report["callback_time"] or "-")}</div>
</div>
{flags}
<h2>Summary</h2><p>{e(report["summary"] or "No summary available.")}</p>
<h2>Customer needs</h2>{items("customer_needs")}
<h2>Objections</h2>{items("objections")}
<h2>Questions asked</h2>{items("questions_asked")}
<h2>Commitments and next steps</h2>{items("commitments")}
<h2>Needs follow-up</h2>
<p class="ev">Requests the agent couldn't answer from the product facts, so the team must reply.</p>
{items("unanswered_requests")}
<h2>Compliance flags</h2>{items("compliance_flags")}
<h2>Verification</h2>
<p class="ev">Every item cites the transcript turns it came from. {len(v["removed_items"])} unsupported item(s)
were removed automatically.{(" " + e(v["error"])) if v.get("error") else ""}</p>
<h2>Transcript</h2>
<table><tr><th>Turn</th><th>Speaker</th><th>What was said</th><th>English</th></tr>{rows}</table>
<p class="ev">Generated {e(_fmt_dt(meta.get("generated_at")))}</p>
</main></body></html>"""


def render_json(report: dict, messages: list[dict]) -> str:
    return json.dumps({"report": report, "transcript": messages}, ensure_ascii=False, indent=2, default=str)
